<?php session_name('VS_CUSTOMER');session_start();if(!isset($_SESSION['user_id'])||($_SESSION['user_role']??'')!=='user'){header('Location: login.php');exit;}require_once 'includes/header.php';?>
<section class="page-shell"><div class="section-head"><div><span class="eyebrow dark">MY BOOKINGS</span><h1>Your rental journey</h1></div><a class="btn" href="vehicles.php">New booking</a></div><div class="booking-tabs"><button class="active" onclick="setFilter('',this)">All</button><button onclick="setFilter('Pending',this)">Pending</button><button onclick="setFilter('Approved',this)">Payment due</button><button onclick="setFilter('Confirmed',this)">Confirmed</button><button onclick="setFilter('Active',this)">Active</button><button onclick="setFilter('Returned',this)">Returned</button><button onclick="setFilter('Completed',this)">Completed</button></div><div id="bookingCards" class="booking-list"></div></section>
<div id="payModal" class="modal"><div class="modal-card"><button class="modal-close" onclick="closePay()">×</button><span class="eyebrow dark">DEMO PAYMENT</span><h2>Complete payment</h2><p class="muted">Simulation only — no real money is charged.</p><div class="payment-methods"><label><input type="radio" name="method" value="UPI" checked> UPI</label><label><input type="radio" name="method" value="Card"> Card</label></div><div class="pay-summary"><span>Amount</span><strong id="payAmount">₹0</strong></div><button class="btn wide" onclick="completePay()">Complete demo payment</button></div></div><div id="receiptModal" class="modal"><div class="modal-card receipt-card"><button class="modal-close" onclick="closeReceipt()">×</button><span class="eyebrow dark">VS TRAVELLS</span><h2>Demo Payment Receipt</h2><p class="muted">Simulation receipt — no real money was charged.</p><div id="receiptBody"></div><button class="btn wide" onclick="window.print()">Print / Save Receipt</button></div></div>
<script>
let all=[],filter='',payId='',payBooking=null,lastSnapshot='',loading=false;
const stages=['Pending','Approved','Confirmed','Active','Returned','Completed'];
function timeline(s){let n=stages.indexOf(s);if(n<0)return'';return `<div class="status-timeline">${['Request','Approved','Paid','Active','Returned','Completed'].map((x,i)=>`<span class="${i<=n?'done':''}">${x}</span>`).join('')}</div>`}
async function load(silent=false){if(loading)return;loading=true;try{const j=await vsJsonFetch('api/bookings/history.php');const next=JSON.stringify(j.data||[]);if(next!==lastSnapshot){all=j.data||[];lastSnapshot=next;render();if(silent)toast('Booking status updated automatically.','success')}}catch(e){}finally{loading=false}}
function setFilter(f,b){filter=f;document.querySelectorAll('.booking-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render()}
function render(){const a=filter?all.filter(x=>x.status===filter):all;bookingCards.innerHTML=a.length?a.map(b=>`<article class="booking-card"><div class="booking-icon">${b.vehicleType==='Bike'?'🏍':'🚘'}</div><div class="booking-info"><div><span class="badge ${b.status.toLowerCase()}">${b.status}</span><h3>${b.vehicleName}</h3><p>${b.startDate} → ${b.endDate} • ${b.totalDays} day${b.totalDays>1?'s':''}</p><div class="booking-details-grid"><span>Pickup<strong>${safeText(b.pickupLocation)}</strong></span><span>Return<strong>${safeText(b.returnLocation)}</strong></span><span>Price/day<strong>${formatINR(b.pricePerDay)}</strong></span><span>Payment<strong>${safeText(b.paymentStatus)}</strong></span><span>Reference<strong>${safeText(b.paymentReference)}</strong></span></div>${timeline(b.status)}</div><div class="booking-price"><small>Total</small><strong>${formatINR(b.totalPrice)}</strong></div></div><div class="booking-actions">${b.status==='Pending'?'<span class="muted">Waiting for admin approval</span>':''}${b.status==='Approved'?`<button class="btn" onclick="openPay('${b.id}',${b.totalPrice})">Demo Pay & Confirm</button>`:''}${['Pending','Approved'].includes(b.status)?`<button class="btn danger ghost-btn" onclick="cancelB('${b.id}')">Cancel</button>`:''}${b.paymentReference?`<button class="btn secondary" onclick="showReceipt('${b.id}')">View Receipt</button>`:''}${b.status==='Confirmed'?'<span class="confirmed-note">✓ Paid & confirmed • Awaiting pickup</span>':''}${b.status==='Active'?'<span class="confirmed-note">🚘 Rental is active</span>':''}${b.status==='Returned'?'<span class="confirmed-note">✓ Vehicle returned • Awaiting completion</span>':''}${b.status==='Completed'?'<span class="confirmed-note">✓ Rental completed</span>':''}</div></article>`).join(''):'<div class="empty-card">No bookings in this category.</div>'}
function openPay(id,amt){payId=id;payBooking=all.find(b=>b.id===id)||null;document.getElementById('payAmount').textContent=formatINR(amt);document.getElementById('payModal').classList.add('show')}
function closePay(){document.getElementById('payModal').classList.remove('show')}
async function completePay(){const method=document.querySelector('input[name=method]:checked').value,j=await vsJsonFetch('api/bookings/pay.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:payId,method})});closePay();toast(j.message+(j.data?.reference?' Reference: '+j.data.reference:''),j.success?'success':'error');await load();if(j.success)setTimeout(()=>showReceipt(payId),250)}
async function cancelB(id){if(!confirm('Cancel this booking request?'))return;const j=await vsJsonFetch('api/bookings/cancel.php',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});toast(j.message,j.success?'success':'error');load()}
function showReceipt(id){const b=all.find(x=>x.id===id);if(!b||!b.paymentReference)return;receiptBody.innerHTML=`<div class="receipt-lines"><div><span>Booking</span><strong>${b.vehicleName}</strong></div><div><span>Rental dates</span><strong>${b.startDate} → ${b.endDate}</strong></div><div><span>Route</span><strong>${safeText(b.pickupLocation)} → ${safeText(b.returnLocation)}</strong></div><div><span>Amount</span><strong>${formatINR(b.totalPrice)}</strong></div><div><span>Payment</span><strong>${b.paymentStatus}</strong></div><div><span>Reference</span><strong>${b.paymentReference}</strong></div></div><div class="demo-stamp">DEMO PAYMENT</div>`;receiptModal.classList.add('show')}
function closeReceipt(){receiptModal.classList.remove('show')}
load();setInterval(()=>{if(!document.hidden)load(true)},7000);
</script><?php require_once 'includes/footer.php';?>
